+test("RF-006-a: descuento global en porcentaje sobre el total; IVA y neto sobre el total descontado", () => {
+  assert.deepEqual(calcularFactura(LINEAS_RF002, { descuentoGlobal: 10 }), {
+    totalCentavos: 9945,
